"""A minimal behavior tree library with RUNNING-resumption (memory) semantics.

Statuses:
    SUCCESS / FAILURE : terminal for this tick.
    RUNNING           : the node needs more ticks; composites *remember* which
                        child was running and resume there on the next tick
                        ("restart-from-running-child"), so earlier siblings
                        (e.g. conditions already checked) are NOT re-executed.
"""

from enum import Enum, auto


class Status(Enum):
    SUCCESS = auto()
    FAILURE = auto()
    RUNNING = auto()


class Node:
    """Base class. `tick` is called once per AI update; `halt` clears memory."""

    def tick(self, world) -> Status:
        raise NotImplementedError

    def halt(self) -> None:
        pass


# --------------------------------------------------------------------------
# Leaves
# --------------------------------------------------------------------------
class Condition(Node):
    """Leaf that maps a predicate on the world to SUCCESS/FAILURE."""

    def __init__(self, name: str, fn):
        self.name = name
        self.fn = fn

    def tick(self, world) -> Status:
        return Status.SUCCESS if self.fn(world) else Status.FAILURE

    def __repr__(self):
        return f"Condition({self.name!r})"


class Action(Node):
    """Leaf that performs work and returns SUCCESS, FAILURE or RUNNING.

    The callable receives the world and must return a Status.
    """

    def __init__(self, name: str, fn):
        self.name = name
        self.fn = fn

    def tick(self, world) -> Status:
        return self.fn(world)

    def __repr__(self):
        return f"Action({self.name!r})"


# --------------------------------------------------------------------------
# Decorator
# --------------------------------------------------------------------------
class Inverter(Node):
    """Flips SUCCESS<->FAILURE; passes RUNNING through untouched."""

    def __init__(self, child: Node):
        self.child = child

    def tick(self, world) -> Status:
        s = self.child.tick(world)
        if s is Status.SUCCESS:
            return Status.FAILURE
        if s is Status.FAILURE:
            return Status.SUCCESS
        return Status.RUNNING

    def halt(self) -> None:
        self.child.halt()


# --------------------------------------------------------------------------
# Composites with memory ("restart-from-running-child")
# --------------------------------------------------------------------------
class Sequence(Node):
    """Ticks children in order until one returns FAILURE or RUNNING.

    If a child returns RUNNING, the Sequence stores its index and resumes at
    that child on the next tick — earlier children are skipped entirely.
    """

    def __init__(self, *children: Node):
        self.children = list(children)
        self._running_index = 0

    def tick(self, world) -> Status:
        while self._running_index < len(self.children):
            s = self.children[self._running_index].tick(world)
            if s is Status.RUNNING:
                return Status.RUNNING  # keep _running_index for resumption
            if s is Status.FAILURE:
                self._running_index = 0
                return Status.FAILURE
            self._running_index += 1
        self._running_index = 0
        return Status.SUCCESS

    def halt(self) -> None:
        self._running_index = 0
        for child in self.children:
            child.halt()


class Selector(Node):
    """Ticks children in order until one returns SUCCESS or RUNNING.

    Same memory rule as Sequence: a RUNNING child is resumed directly on the
    next tick, without re-running earlier (higher-priority) siblings.
    """

    def __init__(self, *children: Node):
        self.children = list(children)
        self._running_index = 0

    def tick(self, world) -> Status:
        while self._running_index < len(self.children):
            s = self.children[self._running_index].tick(world)
            if s is Status.RUNNING:
                return Status.RUNNING
            if s is Status.SUCCESS:
                self._running_index = 0
                return Status.SUCCESS
            self._running_index += 1
        self._running_index = 0
        return Status.FAILURE

    def halt(self) -> None:
        self._running_index = 0
        for child in self.children:
            child.halt()

