def make_guard_tree():
    """Selector: chase > idle-at-post > walk-back-to-post."""
    at_post = lambda w: w["dist_from_post"] == 0
    return Selector(
        Sequence(
            Condition("intruder_visible?", lambda w: w["intruder_visible"]),
            Action("chase", _chase),
        ),
        Sequence(
            Condition("at_post?", at_post),
            Action("idle_scan", _idle_scan),
        ),
        Sequence(
            Inverter(Condition("not_at_post?", at_post)),
            Action("walk_to_post", _walk_to_post),
        ),
    )

